function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  hrUrl: 'https://httpbin.org/post',
  iamUrl: 'https://httpbin.org/post',
  itUrl: 'https://httpbin.org/post',
  saasUrl: 'https://httpbin.org/post',
  timeoutMs: 20000,
  defaultDepartment: 'General',
  defaultRole: 'employee',
  saasApps: ['slack', 'google_workspace', 'notion', 'github'],
  allowSimulation: true
};

const hook = ref('Webhook - New Hire Request');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const firstName = String(body.firstName || body.first_name || '').trim();
const lastName = String(body.lastName || body.last_name || '').trim();
const email = String(body.email || body.workEmail || '').trim().toLowerCase();
const startDate = String(body.startDate || body.start_date || '').trim();
const department = String(body.department || CONFIG.defaultDepartment).trim();
const title = String(body.title || body.jobTitle || 'Team Member').trim();
const managerEmail = String(body.managerEmail || body.manager_email || '').trim().toLowerCase();
const employeeId = String(body.employeeId || body.employee_id || ('EMP-' + Date.now())).trim();

if (!firstName) errors.push('firstName is required');
if (!lastName) errors.push('lastName is required');
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('valid email is required');
if (!startDate) errors.push('startDate is required');

const valid = errors.length === 0;
const fullName = (firstName + ' ' + lastName).trim();

let hrUrl = CONFIG.hrUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  hrUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    employee: {
      employeeId,
      firstName,
      lastName,
      fullName,
      email,
      startDate,
      department,
      title,
      managerEmail: managerEmail || null,
      role: body.role || CONFIG.defaultRole
    },
    urls: {
      hr: hrUrl,
      iam: CONFIG.iamUrl,
      it: CONFIG.itUrl,
      saas: CONFIG.saasUrl
    },
    requestId: body.requestId || ('onboard-' + Date.now())
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Validate & Normalize');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }

const hrOk = status >= 200 && status < 300;
const hrId = (body && (body.id || body.employeeId)) || ctx.employee.employeeId;

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    employee: ctx.employee,
    urls: ctx.urls,
    results: {
      hr: { ok: hrOk, status, id: hrId }
    },
    iamPayload: {
      email: ctx.employee.email,
      displayName: ctx.employee.fullName,
      department: ctx.employee.department,
      title: ctx.employee.title,
      employeeId: hrId,
      role: ctx.employee.role
    }
  }
}];

