function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process IT Result');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }

const saasOk = status >= 200 && status < 300;
const results = {
  ...ctx.results,
  saas: { ok: saasOk, status, apps: ctx.config.saasApps }
};

const allOk = results.hr.ok && results.iam.ok && results.it.ok && results.saas.ok;
const partial = [results.hr.ok, results.iam.ok, results.it.ok, results.saas.ok].filter(Boolean).length;

return [{
  json: {
    requestId: ctx.requestId,
    employee: ctx.employee,
    results,
    summary: {
      status: allOk ? 'completed' : (partial > 0 ? 'partial' : 'failed'),
      systemsOk: partial,
      systemsTotal: 4,
      completedAt: new Date().toISOString()
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Build Final Status');

const httpStatus = ctx.summary.status === 'completed' ? 201 : (ctx.summary.status === 'partial' ? 207 : 502);

const body = {
  status: ctx.summary.status,
  requestId: ctx.requestId,
  employee: {
    employeeId: ctx.employee.employeeId,
    fullName: ctx.employee.fullName,
    email: ctx.employee.email,
    department: ctx.employee.department,
    startDate: ctx.employee.startDate
  },
  provisioning: ctx.results,
  summary: ctx.summary
};

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.requestId
  }
}];
